export const meta = {
  name: 'pr-adversarial-review-chips',
  description: 'Adversarial preflight over the chips-triage diff (dead-code deletion, docs reframing, meta-govern number)',
  phases: [{ title: 'Hunt' }, { title: 'Verify' }],
}

const REPO = '/Users/elmabi/Desktop/my-projets/personal-budget-app'
const CONTEXT = 'Adversarially review the committed diff that will become a PR at ' + REPO + '.\n' +
  'Run: git -C ' + REPO + ' diff main...HEAD  and read the full changed files + relevant siblings.\n' +
  'The change has 3 parts: (1) DELETION of dead code — src/react-app/components/tools/CurrencyConverter.tsx, components/ui/CurrencyConverter.tsx, utils/currency.ts — plus reworded comments in utils/uploadToConvexStorage.ts, utils/uploadToConvexStorage.test.ts, utils/cleanupLegacyGeminiKeys.ts; (2) DOCS reframing Firestore->Convex-as-complete in README.md + docs/architecture.html + docs/personal-budget-app-spec.html + docs/agent-playbook.html + docs/data-model.html; (3) .claude/.meta-govern.json components 52->54 + an errata block appended to docs/audits/2026-07-03-meta-govern-audit.html.\n' +
  'pnpm validate already PASSES (1406 tests, tsc -b, tsc -p convex, docs guards, size-guard) so pure type/compile/dangling-import defects are already excluded — do NOT re-report those; verify anything you claim against the real code/tree.\n' +
  'A finding is reportable if it fails ANY gate:\n' +
  ' - CORRECTNESS: the deletion removed something still referenced at runtime, or a reworded comment now states something false, or a code path broke (tsc says no, but check runtime-only refs like string keys, dynamic import, lazy()).\n' +
  ' - FACTUAL/WIRING (docs): a doc now asserts a Convex mechanism/API/symbol that does NOT exist in the codebase (fabricated specific), OR still frames Firestore as the LIVE backend, OR a dead link / orphan anchor / broken href introduced by the edits, OR the meta-govern number 54 does not match the authoritative computation.\n' +
  ' - THEME/STYLE hygiene only for real violations (raw hex where a token is required) — but these are prose/doc edits, unlikely.\n' +
  '"Correct today" does not excuse a fabricated doc claim or a stale live-backend framing. Refute ONLY pure taste/wording.'

const FINDINGS = { type:'object', additionalProperties:false, required:['findings'], properties:{ findings:{ type:'array', items:{
  type:'object', additionalProperties:false,
  required:['title','file','line','class','severity','scenario','suggestedFix'],
  properties:{ title:{type:'string'}, file:{type:'string'}, line:{type:'string'},
    class:{type:'string', enum:['correctness','convention','wiring','factual','style']},
    severity:{type:'string', enum:['P1','P2','P3']}, scenario:{type:'string'}, suggestedFix:{type:'string'} } } } } }

const VERDICT = { type:'object', additionalProperties:false, required:['mustFix','class','reasoning'],
  properties:{ mustFix:{type:'boolean'},
    class:{type:'string', enum:['correctness','convention','wiring','factual','style']},
    evidence:{type:'string', description:'the real code/tree/computation fact that confirms or refutes the finding'},
    confidence:{type:'string',enum:['high','medium','low']}, reasoning:{type:'string'} } }

const DIMENSIONS = [
  { key:'dead-code-safety', focus:'The DELETIONS. Prove nothing still references the removed files at runtime: check string-keyed lookups, dynamic import(), React.lazy, route tables, barrel re-exports (index.ts), and the reworded comments in uploadToConvexStorage.ts/.test.ts and cleanupLegacyGeminiKeys.ts — do the reworded comments now assert anything false, or leave a dangling reference? Grep the repo for CurrencyConverter and utils/currency.' },
  { key:'docs-factual', focus:'The DOCS edits (README + architecture/spec/agent-playbook/data-model). For EACH factual claim the edits introduce about the current backend, VERIFY it against the code: does the asserted Convex symbol/mechanism actually exist (grep convex/ and src/ — e.g. translateConvexError, requireUser, useQuery/useMutation, by_user index, VITE_CONVEX_URL in .env.example)? Does any edited passage still wrongly call Firestore the LIVE backend? Did an edit break an in-page anchor/href or the docs-map contract? Is the README Convex-setup step grounded in real env vars/scripts, not invented?' },
  { key:'govern-number', focus:'The .claude/.meta-govern.json components:54 change and the audit errata. Recompute the authoritative unique C-XX count from docs/composants/catalogue-composants.html exactly as meta-govern does (regex /\\bC-\\d+/g into a Set) and confirm it equals 54. Confirm ONLY the components field changed (funcIds 16, tests 471, metaGovernVersion 1.13.0 untouched). Confirm the errata is appended (historical finding text not rewritten) and its claimed count (54) and any TOC/nav anchor it added are internally consistent (no dead anchor).' },
]

phase('Hunt')
const results = await pipeline(
  DIMENSIONS,
  (d) => agent(CONTEXT + '\n\nDIMENSION: ' + d.focus, { label:'hunt:'+d.key, phase:'Hunt', schema:FINDINGS, effort:'high' }),
  (review) => parallel((review?.findings ?? []).map((f) => () =>
    agent(CONTEXT + '\n\nADVERSARIALLY VERIFY this finding. Check its FACTS against the real code/tree/computation first, then set mustFix (TRUE for a real correctness break or a fabricated/stale doc claim or a dead link or a wrong number; FALSE for pure wording/taste or if the facts do not hold).\n\n' + JSON.stringify(f,null,2),
      { label:'verify:'+f.file+':'+f.line, phase:'Verify', schema:VERDICT, effort:'high' })
      .then((v) => ({ finding:f, verdict:v }))))
)

function dedupe(items) {
  const merged = []
  for (const item of items) {
    const f = item.finding
    const lineNum = String(f.line).match(/\d+/)?.[0]
    const twin = merged.find((m) => m.finding.file === f.file && (lineNum ? String(m.finding.line).includes(lineNum) : m.finding.line === f.line))
    if (twin) twin.duplicateCount = (twin.duplicateCount ?? 1) + 1
    else merged.push({ ...item, duplicateCount: 1 })
  }
  return merged
}

const confirmed = dedupe(results.flat().filter(Boolean).filter((r) => r?.verdict?.mustFix))
return { verdict: confirmed.length ? 'FINDINGS' : 'PASS', confirmed: confirmed.map((r) => ({ ...r.finding, verdict:r.verdict, duplicateCount:r.duplicateCount })) }

